"""Small scoped tools wrapping Hermes's native vault and browser fill path."""
import json
from urllib.parse import urlsplit

from .service import binding
from .store import AccessError

TOOLS = ['clanker_request_access','clanker_vault_list','clanker_vault_fill','clanker_vault_enter_code','clanker_request_payment','clanker_pay','clanker_api_request','clanker_personal_fill']


def execute(name,args,**kwargs):
    try:
        turn = binding(kwargs.get('task_id'))
        service = turn.service
        if name=='clanker_request_access':
            return json.dumps(service.call(service.request_access(turn,**args)))
        if name=='clanker_request_payment':
            return json.dumps(service.call(service.payments.request(turn,**args)))
        try:home = service.assert_private(turn)
        except AccessError:
            return json.dumps(service.call(service.move_private(turn)))
        if name=='clanker_api_request':
            from .api import execute as api_request
            return json.dumps(api_request(turn, **args))
        if name=='clanker_personal_fill':
            return json.dumps(service.personal.fill(turn, **args))
        from agent.vault_store import VaultStore
        from tools import browser_vault_tool as native
        with service.lock_for(home):
            if name=='clanker_pay':
                if set(args)!={'request_id'}:raise AccessError('Use only the approved purchase request id.')
                return json.dumps(service.payments.execute(turn,args['request_id']))
            store = VaultStore(home/'vault')
            if name=='clanker_vault_list':
                return json.dumps({'items':service.delegations.items(turn.source.scope_id,turn.source.user_id),
                    'personal_info':service.personal.store(turn.source.scope_id,turn.source.user_id).summary(),
                    'personal_info_url':service.config['public_url'].rstrip('/')+'/vault'})
            access = service.delegations.resolve(turn,args['handle'])
            meta = access.meta
            store = VaultStore(access.home/'vault')
            if meta.kind!='login':
                raise AccessError('Browser fill and verification require a saved login, not an API key.')
            from .payments import local_supervisor
            if service.cloud_browser is not None and local_supervisor(turn.task_id) is None:
                cloud=service.cloud_browser
                if name=='clanker_vault_fill':
                    return json.dumps(cloud.fill(turn,meta,access=access))
                if name=='clanker_vault_enter_code':
                    from agent.vault_store import totp_now
                    cloud.login_origin(turn,meta.origin,otp=True)
                    secret=store.resolve_secret(meta.id)
                    code=totp_now(secret['otp_secret']) if secret.get('otp_secret') else service.store.consume_code(
                        team=turn.source.scope_id,owner=turn.source.user_id,
                        home=service.private_home(turn.source.scope_id,turn.source.user_id),
                        task_id=turn.task_id,handle=access.handle,origin=meta.origin)
                    if not code:
                        return json.dumps(service.call(service.request_code(turn,meta,access=access)))
                    return json.dumps(cloud.fill(turn,meta,code=code,access=access))
            from seatbelt.context import Context
            supervisor = native._ensure_supervisor(turn.task_id)
            if supervisor is None:
                raise AccessError('Start this task\'s private browser before filling the login.',409)
            Context(home).owned_cdp(supervisor.cdp_url)
            service.delegations.check_execution(turn)
            if name=='clanker_vault_fill':
                if meta.login_method=='sms':
                    from .login import local_fill
                    with service.lock_for(access.home):return json.dumps(local_fill(turn,access))
                if access.grant_id or access.home!=turn.home:
                    with service.lock_for(access.home):
                        return service.delegations.fill_local(turn,access)
                return native.browser_vault_fill(meta.id,task_id=turn.task_id)
            if name=='clanker_vault_enter_code':
                if meta.login_method=='sms':
                    from .login import OTP_FIELDS, local_fill
                    found=supervisor.focus_page(meta.origin,accept=OTP_FIELDS)
                    if not found.get('ok') or native._current_page_origin(turn.task_id)!=meta.origin:
                        raise AccessError('Open the matching SMS verification form before requesting its code.',403)
                    code=service.store.consume_code(team=turn.source.scope_id,owner=turn.source.user_id,
                        home=service.private_home(turn.source.scope_id,turn.source.user_id),
                        task_id=turn.task_id,handle=access.handle,origin=meta.origin)
                    if not code:return json.dumps(service.call(service.request_code(turn,meta,access=access)))
                    with service.lock_for(access.home):return json.dumps(local_fill(turn,access,code=code))
                # Stock OTP generation lacks a handle-to-current-origin check;
                # apply the same exact-origin authorization as password filling.
                native._focus_bound_origin(turn.task_id,str(meta.origin),'otp')
                if native._current_page_origin(turn.task_id)!=meta.origin:
                    raise AccessError('The verification page does not match this saved account.',403)
                code=service.store.consume_code(team=turn.source.scope_id,owner=turn.source.user_id,
                    home=service.private_home(turn.source.scope_id,turn.source.user_id),
                    task_id=turn.task_id,handle=access.handle,origin=meta.origin)
                if access.grant_id or access.home!=turn.home:
                    from agent.vault_store import totp_now
                    secret=access.secret()
                    code=totp_now(secret['otp_secret']) if secret.get('otp_secret') else code
                    if not code:
                        return json.dumps(service.call(service.request_code(turn,meta,access=access)))
                    with service.lock_for(access.home):
                        return service.delegations.fill_local(turn,access,code=code)
                result=native.browser_vault_enter_code(meta.id,task_id=turn.task_id,
                    expected_origin=meta.origin,provided_code=code)
                del code
                if json.loads(result).get('error_type')=='prompt_unavailable':
                    return json.dumps(service.call(service.request_code(turn,meta)))
                return result
        raise AccessError('This credential operation is unavailable.')
    except AccessError as error:
        return json.dumps({'success':False,'error':str(error),'status':error.status})
    except Exception:
        return json.dumps({'success':False,'error':'The credential operation could not complete. No secret has been returned.'})


def register_tools(ctx):
    definitions = {
        'clanker_personal_fill':(
            'Fill the requester\'s primary phone, email or delivery address from their private vault into the exact HTTPS website requested by their task. Use only details that the task needs, never another person\'s values. Saved website-specific login details take precedence. This fills visible fields and never submits forms, sends messages, signs up or buys. Local browser only. Secret values are never returned; if missing, direct the owner to Personal info in their vault.',
            {'origin':{'type':'string','description':'Exact HTTPS origin of the intended open website, with no path or query.'},
             'fields':{'type':'array','items':{'type':'string','enum':['phone','email','address']},'minItems':1,'maxItems':3}},['origin','fields']),
        'clanker_request_access':(
            'Request a private hosted credential form. For website logins, use kind login while the actual HTTPS login page is open. For API keys, use kind api_key, a service-specific label for the form title, and the exact HTTPS API origin; no browser is required. Shared-channel tasks use isolated requester-owned execution; the login link is sent to DM and the final requested result returns to the original thread. Never ask for credentials in chat, local key files or environment variables. The handler sends the link; saving resumes the task automatically.',
            {'use_primary':{'type':'boolean','default':True,'description':'Reuse an existing SMS login first, or the primary phone for a new site. Use false only when the owner chooses a different phone; a browser failure or expired SMS code does not require collecting the number again.'},'kind':{'type':'string','enum':['login','api_key'],'default':'login'},'login_method':{'type':'string','enum':['auto','password','sms'],'default':'auto','description':'Use sms for phone-number + SMS-code login. Local auto detects a phone-only first step. Use password if a password follows the phone number. Collect phone numbers privately, never supply them as identifier.'},'label':{'type':'string','description':'Form title supplied by this request. Required for API keys; identify the service and credential being collected.','maxLength':120},'origin':{'type':'string','description':'Required only for API keys: exact HTTPS API origin, with no path, query, fragment or embedded credentials.'},'identifier':{'type':'string','description':'Known email or username for password login forms only. Never a phone number, password or API key.'}},[]),
        'clanker_vault_list':('Check saved details before asking the requester to repeat an email, phone or address. List this requester\'s own and explicitly invited login, card and API-key handles and metadata, plus masked primary personal details. An owned login email can be offered for confirmation in the owner\'s private DM when a required field needs it; a different website needs that confirmation. Skip optional fields. Invited identifiers are not the requester\'s personal defaults. Invited handles can be used on the owner\'s behalf, never reshared. Shared requests start isolated execution with a private login detour and reply to the original thread. Secret values are never returned.',{},[]),
        'clanker_api_request':('Call the exact HTTPS service bound to an owned or invited API-key handle. The backend adds authentication; never supply the key in the task, path, body or headers. Redirects and host-local destinations are refused. This can perform external changes: use only for the user\'s requested operation; check outcomes before retrying.',
            {'handle':{'type':'string'},'path':{'type':'string','description':'Relative path and optional query beginning with one slash.'},
             'method':{'type':'string','enum':['GET','POST','PUT','PATCH','DELETE','HEAD'],'default':'GET'},
             'body':{'description':'Optional JSON request body.'},'headers':{'type':'object','additionalProperties':{'type':'string'}},
             'auth_header':{'type':'string','enum':['Authorization','x-api-key','X-API-Key','api-key'],'default':'Authorization'},
             'auth_scheme':{'type':'string','enum':['Bearer',''],'default':'Bearer'}},['handle','path']),
        'clanker_request_payment':('Request an owner-only card and purchase approval form for the current local checkout. The backend captures its actual origin and checkout contents. Specify the exact merchant, items/quantities and final total including fees. Optional handle selects a saved card. No card details enter chat. Shared requests move to DM. End the turn while waiting; approval resumes it. Cloud browsers cannot receive card data.',
            {'checkout_url':{'type':'string','description':'Exact URL of the open HTTPS checkout tab in the private local browser.'},
             'merchant':{'type':'string','maxLength':120},'summary':{'type':'string','maxLength':1000},
             'amount_minor':{'type':'integer','description':'Final total including fees, in minor units: INR 699.00 is 69900 paise.'},
             'currency':{'type':'string','enum':['INR','USD','EUR','GBP','CAD','AUD'],'default':'INR'},
             'handle':{'type':'string','description':'Optional private saved-card handle for this checkout origin.'}},['checkout_url','merchant','summary','amount_minor']),
        'clanker_pay':('Execute the owner-approved purchase in the original local supervised checkout. The backend checks owner, conversation, browser, page contents and payment button and consumes approval before card fill and submission. Each purchase needs fresh approval; unknown outcomes cannot be replayed. A submitted result is not proof of payment: verify the merchant receipt. Bank approval may still need the owner.',
            {'request_id':{'type':'string'}},['request_id']),
        'clanker_vault_fill':('Fill a saved password or SMS-login phone number into this task\'s browser on its exact permitted origin. For SMS logins, never type the masked identifier; this tool fills the private number. Then request the website\'s SMS code and use clanker_vault_enter_code. Password logins: type the metadata username first. No secret is returned.',{'handle':{'type':'string'}},['handle']),
        'clanker_vault_enter_code':('Enter an authenticator or current SMS/email verification code on the saved login origin, including passwordless SMS logins. Without a setup key, send a private hosted one-time-code form and resume automatically after submission. Each SMS login requires a fresh code; never ask for it in chat. No code or setup key is returned.',{'handle':{'type':'string'}},['handle']),
    }
    for name,(description,properties,required) in definitions.items():
        schema={'name':name,'description':description,'parameters':{'type':'object','properties':properties,'required':required,'additionalProperties':False}}
        ctx.register_tool(name,'clanker_browser',schema,lambda args,_name=name,**kwargs:execute(_name,args,**kwargs),description=description,emoji='🔐')
"""Hermes plugin using the native terminal provider ABC and toolset resolver."""
import json
from pathlib import Path
import subprocess
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from seatbelt.context import Context
from agent.terminal_env_provider import TerminalEnvironmentProvider
from hermes_constants import get_hermes_home
from tools.environments.local import LocalEnvironment


def browser_tools():
    context=Context(get_hermes_home())
    config=Path(context.settings['transport_home'])/'.clanker-cloud/config.json'
    if config.exists() and json.loads(config.read_text()).get('enabled'):
        from cloud_browser.tools import TOOLS
        return [*TOOLS,'browser_exec']
    return ['browser_exec']


def discovery_tools():
    from public_web.tools import enabled, TOOLS
    context = Context(get_hermes_home())
    path = Path(context.settings['transport_home']) / '.clanker-cloud/config.json'
    if enabled(context.home) and path.exists():
        settings = json.loads(path.read_text())
        if settings.get('enabled') and settings.get('provider') == 'browser_tool':
            return list(TOOLS)
    return []


class SeatbeltEnvironment(LocalEnvironment):
    _sudo_nopasswd_probe_supported = False

    def __init__(self, *, cwd, timeout):
        self.execution = Context(get_hermes_home())
        base = self.execution.home / "workspace"
        path = Path(cwd).resolve() if cwd else base
        if not any(path.is_relative_to(root) for root in (base, self.execution.home / "artifacts")):
            raise RuntimeError("Terminal cwd is outside this context")
        super().__init__(cwd=str(path), timeout=timeout,
                         env={"TERMINAL_TEMP_DIR": str(self.execution.terminal)})

    def get_temp_dir(self):
        return str(self.execution.terminal)

    def _run_bash(self, cmd_string, *, login=False, timeout=120, stdin_data=None):
        context = Context(self.execution.home)
        env = context.safe_env()
        env["TERMINAL_TEMP_DIR"] = str(context.terminal)
        proc = subprocess.Popen(context.command(["/bin/bash", "-c", cmd_string]),
                                env=env, cwd=self.cwd, text=True, encoding="utf-8", errors="replace",
                                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                stdin=subprocess.PIPE if stdin_data is not None else subprocess.DEVNULL,
                                start_new_session=True, close_fds=True)
        if stdin_data is not None:
            from tools.environments.base_output import _pipe_stdin
            _pipe_stdin(proc, stdin_data)
        return proc


class SeatbeltProvider(TerminalEnvironmentProvider):
    name = "clanker_seatbelt"
    display_name = "Clanker macOS Seatbelt"
    is_remote = False
    is_container = False

    def is_available(self):
        try:
            Context(get_hermes_home())
            return True
        except Exception:
            return False

    def create_environment(self, *, cwd, timeout, **kwargs):
        return SeatbeltEnvironment(cwd=cwd, timeout=timeout)


def gate(tool_name, args, next_call, **kwargs):
    try:
        context = Context(get_hermes_home())
        from vault.tools import TOOLS as vault_tools
        if tool_name in vault_tools or tool_name in discovery_tools() or tool_name in browser_tools() and tool_name!='browser_exec':
            return next_call(args)
        if tool_name not in {"browser_exec", "terminal"}:
            return json.dumps({"success": False, "error": "Tool is outside this context's browser policy"})
        allowed = ({'code', 'session', 'timeout_s'} if tool_name == 'browser_exec' else
                   {'command', 'timeout', 'background', 'workdir', 'pty', 'notify_on_complete', 'watch_patterns', 'heartbeat'})
        if set(args) - allowed:
            return json.dumps({'success': False, 'error': 'Unsupported execution arguments'})
        if not context.settings.get('activated'):
            return json.dumps({'success': False, 'error': 'Execution unavailable: operator acceptance is pending'})
        from agent.gateway_context import current_gateway_turn
        current = current_gateway_turn()
        if current is not None:
            from vault.service import binding
            turn = binding(current.task_id)
            turn.service.delegations.check_execution(turn)
            turn.service.personal.register_redactions(turn)
        if tool_name == "terminal" and args.get("background"):
            return json.dumps({"success": False, "error": "Use foreground terminal calls in the current browser POC"})
        if tool_name == 'terminal' and args.get('pty'):
            return json.dumps({'success': False, 'error': 'PTY execution is unavailable in the current browser POC'})
        return next_call(args)
    except Exception as error:
        return json.dumps({"success": False, "error": "Execution unavailable: " + str(error)})


def register(ctx):
    from toolsets import create_custom_toolset
    from vault.tools import register_tools, TOOLS as vault_tools
    ctx.register_terminal_environment_provider(SeatbeltProvider())
    from vault.service import on_gateway_control
    ctx.register_hook('on_gateway_control', on_gateway_control)
    register_tools(ctx)
    selected=browser_tools()
    if selected!=['browser_exec']:
        from cloud_browser.tools import register_tools as register_cloud
        register_cloud(ctx)
    discovery = discovery_tools()
    if discovery:
        from public_web.tools import register_tools as register_discovery
        register_discovery(ctx)
    create_custom_toolset("clanker_browser", "Browser, public discovery and private access", tools=[*selected, *discovery, "terminal", *vault_tools])
    ctx.register_middleware("tool_execution", gate)
    from clanker_policy import EXECUTION_POLICY, BROWSER_HANDOFF_POLICY
    ctx.register_system_prompt_section('clanker.execution', EXECUTION_POLICY)
    ctx.register_system_prompt_section('clanker.browser_handoff', BROWSER_HANDOFF_POLICY)
    ctx.register_system_prompt_section('clanker.payments',
        'For purchases, prepare the checkout in the private LOCAL browser using browser_exec, even when cloud browsing is configured. '
        'Local login/password and code tools use the local supervised browser when one is active. '
        'Use clanker_request_payment with the exact checkout_url, merchant, exact order summary, final amount_minor including fees, currency and an optional saved-card handle. '
        'The private form saves reusable card number/expiry and requests a temporary CVV plus explicit approval for this purchase. '
        'Invited card handles request that approval from the card owner, while the purchase resumes in the original requester\'s private task. '
        'Every purchase needs a fresh form, including use of a merchant-saved payment method. Never submit a payment with browser_exec, terminal or the cloud browser. '
        'End the turn after waiting_for_owner; the saved approval resumes it with a request_id for clanker_pay. '
        'Do not change the cart after approval. A changed checkout requires a new form. '
        'Do not send card details or CVV to Composio, a browser task prompt, Slack, local files or environment variables. '
        'After clanker_pay, verify the merchant receipt; submitted is not paid. An unknown result must be reconciled before a new payment. '
        'The current handler supports one-time top-level card checkout forms with one clear Pay/Place order button. '
        'If the checkout uses unsupported frames, a wallet, a subscription, or bank approval, stop and explain the required owner action.')
    ctx.register_system_prompt_section('clanker.api_keys',
        'For a user-supplied API key, check clanker_vault_list privately for saved access, then use '
        'clanker_request_access with kind api_key, a service-specific form title in label, and the exact HTTPS API origin. '
        'The title comes from the request; the template is shared across services. Do not open a browser login page for an API key. '
        'Never ask a Slack user to paste secrets, save a key in a local file, or configure an environment variable. '
        'After waiting_for_owner or moved_to_private, end the turn and wait for the hosted save to resume it. '
        'Use clanker_api_request with an owned or invited API-key handle and a relative API path to perform authorized API work. '
        'The backend supplies authentication on the saved exact HTTPS origin. Choose Authorization with Bearer, or the service\'s supported API-key header with an empty auth_scheme. '
        'Never supply or reveal the raw key. Invited handles grant use on the owner\'s behalf, not onward sharing. '
        'Use only the user-requested HTTP operation, and check uncertain outcomes before repeating work with side effects.')
    ctx.register_system_prompt_section('clanker.personal_info',
        'Primary email, phone and delivery address live in Personal info in the private vault, separate from memory and credential invitations. '
        'Before asking the user for a personal detail, inspect the actual form and check clanker_vault_list plus the current conversation. '
        'Omit optional fields unless the task needs them; do not ask for an email merely because the form has an email field. '
        'Personal info returns availability and masked summaries; saved login metadata can include a visible email identifier. '
        'If a required email is already known, ask one concise confirmation such as "Do you want me to use <saved email> here?" in the owner\'s private DM. '
        'An owned login email from another website is a candidate, not an established primary or permission to reuse it. '

