from pathlib import Path
import re,difflib
root=Path.cwd()
text=(root/"scripts/apply-hermes-mods").read_text().split("baseline =",1)[0]
patches=[root/p for p in re.findall(r"patches/hermes/[a-z0-9-]+\.patch",text)]
files={}
for patch in patches:
    for p in re.findall(r"^(?:--- a/|\+\+\+ b/)([^\n]+)$",patch.read_text(),re.M):
        files[p]=(root/p).read_text().splitlines(True) if (root/p).is_file() else []
original={p:list(lines) for p,lines in files.items()}
def apply(patch,reverse=False):
    source=patch.read_text().splitlines(True)
    i=0
    while i<len(source):
        if not source[i].startswith("--- "):
            i+=1;continue
        old=source[i][4:].strip();new=source[i+1][4:].strip()
        path=(old if old!="/dev/null" else new)[2:]
        i+=2;offset=0
        while i<len(source) and source[i].startswith("@@ "):
            header=source[i];i+=1;hunk=[]
            while i<len(source) and not source[i].startswith(("@@ ","diff --git ","--- ")):
                if source[i].startswith((" ","+","-")):hunk.append(source[i])
                i+=1
            match=re.match(r"@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@",header)
            start=int(match.group(3 if reverse else 1))
            count=int(match.group(4 if reverse else 2) or 1)
            before=[line[1:] for line in hunk if line[0] in (" ","+" if reverse else "-")]
            after=[line[1:] for line in hunk if line[0] in (" ","-" if reverse else "+")]
            lines=files[path];pos=(start-1 if count else start)+offset
            if lines[pos:pos+len(before)]!=before:
                found=[j for j in range(len(lines)-len(before)+1) if lines[j:j+len(before)]==before]
                if len(found)!=1:
                    raise RuntimeError(f"{patch.name}: {path}: {header.strip()} matching positions {found[:4]}")
                pos=found[0]
            lines[pos:pos+len(before)]=after
            offset+=len(after)-len(before)

for p in reversed(patches):apply(p,True)
for p in patches:apply(p)
assert files==original
print("All",len(patches),"patches roundtrip with exact line content for",len(files),"paths.")
'

